TERMS = [  # Part B: the Definitions section, our glosses
 ('Compensation', 'credit for a module failed by a small margin, usually on the strength of good overall performance'),
 ('Condonement', 'allowing a student to fail one or more modules, without credit, and still receive the degree'),
 ('Course (of study)', 'an approved, coherent course that normally leads to a qualification; research programmes included'),
 ('Course learning outcomes', 'what a learner is expected to know, understand or do on completing a course; holistic, not the sum of module outcomes'),
 ('Credit', 'a measure of learning, awarded for achieving outcomes at a stated level'),
 ('Cycles', 'the Bologna process\'s sequential levels (short, first, second, third) in which European higher education qualifications sit'),
 ('Degree-awarding body', 'an institution holding degree-awarding powers by one of the routes the definition lists'),
 ('Exit qualification', 'an award made when a student leaves a longer course part way, not registered for at the outset'),
 ('Framework levels', 'stages of similar attainment, in sequence, against which institutions place their qualifications'),
 ('Intermediate qualification', 'a separate award available part way through a longer course, which a student can register for at the outset'),
 ('Level descriptor', 'a statement of the generic characteristics of learning outcomes at one level of a framework, used as a reference point'),
 ('Qualification', 'a degree, diploma or certificate that a competent authority awards; here, a degree-awarding body'),
]
